#!/bin/sh
# Combines the source chunks in src/ into a single, double-clickable index.html
cd "$(dirname "$0")" || exit 1
# 1) embed the recorded sound effects so the game works offline / from file://
{ echo "// generated by build.sh from assets/sfx/*.mp3 (real recorded CC0 sound effects)"; echo "const SFX_DATA = {"; for f in assets/sfx/*.mp3; do printf "  '%s': '%s',\n" "$(basename "$f" .mp3)" "$(base64 < "$f" | tr -d '\n')"; done; echo "};"; printf "const VO_FILES = [%s]; // recorded voice-over found in assets/vo/\n" "$(for f in assets/vo/*.mp3; do [ -e "$f" ] && printf "'%s'," "$(basename "$f" .mp3)"; done)"; } > src/15_sfxdata.js
# 2) stitch everything into one double-clickable page
cat src/00_head.html src/10_core.js src/15_sfxdata.js src/20_audio.js src/30_stage.js src/35_title.js src/40_game.js src/99_tail.html > index.html
echo "Built index.html ($(wc -c < index.html | tr -d ' ') bytes)"
